import { expect, test, uniqueName } from "../../fixtures";

test("submitting a vendor with all three documents extracted moves it to in_review", { tag: "@REV-01" }, async ({ apiAs }) => {
  const member = await apiAs("member");

  const created = await member.post("/api/vendors", {
    data: { name: uniqueName("REV01 Vendor"), category: "software", contact_email: "billing@example.com" },
  });
  expect(created.status(), await created.text()).toBe(201);
  const vendor = await created.json();

  for (const kind of ["w9", "insurance_certificate", "contract"]) {
    const upload = await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind,
        file: { name: `${kind}.pdf`, mimeType: "application/pdf", buffer: Buffer.from("%PDF-1.4 test document") },
      },
    });
    expect(upload.status(), await upload.text()).toBe(201);
  }

  await expect
    .poll(
      async () => {
        const res = await member.get(`/api/vendors/${vendor.id}/documents`);
        const docs = (await res.json()) as { kind: string; status: string }[];
        return docs.length === 3 && docs.every((d) => d.status === "extracted");
      },
      { timeout: 60_000 },
    )
    .toBe(true);

  const submitted = await member.post(`/api/vendors/${vendor.id}/submit`);
  expect(submitted.status(), await submitted.text()).toBe(200);
  expect((await submitted.json()).status, await submitted.text()).toBe("in_review");

  await expect
    .poll(
      async () => {
        const res = await member.get(`/api/vendors/${vendor.id}/audit`);
        const trail = (await res.json()) as { items: { action: string }[] };
        return trail.items.some((e) => e.action === "vendor.submitted");
      },
      { timeout: 30_000 },
    )
    .toBe(true);
});
